drop function if exists public.admin_confirm_manual_deposit(text,numeric,text,text);
drop function if exists public.admin_confirm_manual_deposit(text,numeric,text,text,text,jsonb);
create function public.admin_confirm_manual_deposit(p_folio text,p_amount numeric default null,p_ref_id text default null,p_status text default 'approved',p_reason text default null,p_meta jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_req public.manual_deposit_requests%rowtype; v_status text; v_amount numeric; v_ref text; v_wallet jsonb; v_promo jsonb; v_affiliate jsonb; begin if nullif(trim(p_folio),'') is null then raise exception 'FOLIO_REQUIRED'; end if; select * into v_req from public.manual_deposit_requests where folio=trim(p_folio) for update; if not found then return jsonb_build_object('ok',false,'error','NOT_FOUND','folio',p_folio); end if; v_status:=lower(trim(coalesce(nullif(p_status,''),'approved'))); if v_status not in ('approved','rejected') then return jsonb_build_object('ok',false,'error','INVALID_STATUS'); end if; if v_req.status<>'pending' then if (v_status='approved' and v_req.status in ('approved','confirmed')) or (v_status='rejected' and v_req.status='rejected') then return jsonb_build_object('ok',true,'idempotent',true,'deposit_id',v_req.id,'user_id',v_req.user_id,'amount',v_req.amount,'status',v_req.status); end if; return jsonb_build_object('ok',false,'error','STATUS_CONFLICT','status',v_req.status); end if; v_amount:=coalesce(p_amount,v_req.amount); if v_amount is null or v_amount<=0 then return jsonb_build_object('ok',false,'error','INVALID_AMOUNT'); end if; if p_amount is not null and abs(p_amount-v_req.amount)>0.01 then return jsonb_build_object('ok',false,'error','AMOUNT_MISMATCH'); end if; v_ref:=coalesce(nullif(trim(p_ref_id),''),'manual_deposit:'||v_req.folio); if v_status='rejected' then update public.manual_deposit_requests set status='rejected',reviewed_at=now(),reviewed_by=coalesce(p_meta->>'reviewed_by','admin_api'),updated_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_meta,'{}'::jsonb)||jsonb_build_object('ref_id',v_ref,'reason',p_reason) where id=v_req.id; return jsonb_build_object('ok',true,'idempotent',false,'deposit_id',v_req.id,'user_id',v_req.user_id,'amount',v_amount,'status','rejected'); end if; v_wallet:=public.wallet_apply_delta(p_user_id=>v_req.user_id,p_delta_balance=>v_amount,p_delta_bonus=>0,p_delta_locked=>0,p_reason=>coalesce(nullif(p_reason,''),'deposit_manual'),p_ref_id=>v_ref,p_method=>coalesce(nullif(v_req.method,''),'spei'),p_metadata=>jsonb_build_object('folio',v_req.folio,'deposit_id',v_req.id,'source','admin_confirm_manual_deposit')||coalesce(p_meta,'{}'::jsonb)); if coalesce(v_wallet->>'ok','false')<>'true' then raise exception 'MANUAL_DEPOSIT_WALLET_FAILED'; end if; v_promo:=public.apply_deposit_promo_atomic(v_req.user_id,v_amount,v_req.folio); if coalesce(v_promo->>'ok','true')<>'true' and coalesce(v_promo->>'error','')<>'WAGERING_ALREADY_ACTIVE' then raise exception 'MANUAL_DEPOSIT_PROMO_FAILED'; end if; v_affiliate:=public.credit_affiliate_first_deposit_atomic(v_req.user_id,v_amount,v_req.folio,20,50); if coalesce(v_affiliate->>'ok','true')<>'true' then raise exception 'MANUAL_DEPOSIT_AFFILIATE_FAILED'; end if; update public.manual_deposit_requests set status='approved',reviewed_at=now(),reviewed_by=coalesce(p_meta->>'reviewed_by','admin_api'),updated_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_meta,'{}'::jsonb)||jsonb_build_object('ref_id',v_ref,'reason',p_reason,'wallet_tx_id',v_wallet->>'tx_id','promo',v_promo,'affiliate',v_affiliate) where id=v_req.id; update public.profiles set last_deposit_amount=v_amount,last_deposit_at=now(),updated_at=now() where id=v_req.user_id; return jsonb_build_object('ok',true,'idempotent',coalesce((v_wallet->>'idempotent')::boolean,false),'deposit_id',v_req.id,'user_id',v_req.user_id,'amount',v_amount,'status','approved','wallet',v_wallet,'promo',v_promo,'affiliate',v_affiliate); end; $$;
create or replace function public.admin_settle_withdrawal(p_external_id text,p_final_action text,p_provider_payload jsonb default '{}'::jsonb,p_note text default null,p_idempotency_key text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare v_req public.withdraw_requests%rowtype; v_action text; v_final_status text; v_ref text; v_wallet jsonb; begin if nullif(trim(p_external_id),'') is null then raise exception 'EXTERNAL_ID_REQUIRED'; end if; v_action:=lower(trim(coalesce(p_final_action,''))); if v_action not in ('paid','reject','failed','refund') then return jsonb_build_object('ok',false,'error','INVALID_ACTION'); end if; v_final_status:=case v_action when 'paid' then 'paid' when 'reject' then 'rejected' when 'failed' then 'failed' else 'refunded' end; select * into v_req from public.withdraw_requests where external_id=trim(p_external_id) or id::text=trim(p_external_id) order by created_at desc limit 1 for update; if not found then return jsonb_build_object('ok',false,'error','NOT_FOUND'); end if; if v_req.status in ('paid','rejected','failed','refunded') then if v_req.status=v_final_status then return jsonb_build_object('ok',true,'idempotent',true,'status',v_req.status,'external_id',coalesce(v_req.external_id,v_req.id::text)); end if; return jsonb_build_object('ok',false,'error','FINAL_STATUS_CONFLICT','status',v_req.status,'requested_status',v_final_status); end if; if v_req.status<>'pending' then return jsonb_build_object('ok',false,'error','INVALID_CURRENT_STATUS','status',v_req.status); end if; v_ref:=coalesce(nullif(trim(p_idempotency_key),''),'withdraw_settle:'||coalesce(v_req.external_id,v_req.id::text)||':'||v_final_status); if v_action='paid' then v_wallet:=public.wallet_apply_delta(p_user_id=>v_req.user_id,p_delta_balance=>0,p_delta_bonus=>0,p_delta_locked=>-v_req.amount,p_reason=>'withdraw_paid',p_ref_id=>v_ref,p_method=>coalesce(nullif(v_req.method,''),'spei'),p_metadata=>jsonb_build_object('withdraw_request_id',v_req.id,'external_id',v_req.external_id,'note',p_note)); else v_wallet:=public.wallet_apply_delta(p_user_id=>v_req.user_id,p_delta_balance=>v_req.amount,p_delta_bonus=>0,p_delta_locked=>-v_req.amount,p_reason=>'withdraw_refund',p_ref_id=>v_ref,p_method=>coalesce(nullif(v_req.method,''),'spei'),p_metadata=>jsonb_build_object('withdraw_request_id',v_req.id,'external_id',v_req.external_id,'final_status',v_final_status,'note',p_note)); end if; if coalesce(v_wallet->>'ok','false')<>'true' then raise exception 'WITHDRAW_WALLET_SETTLEMENT_FAILED'; end if; update public.withdraw_requests set status=v_final_status,provider_payload=coalesce(provider_payload,'{}'::jsonb)||coalesce(p_provider_payload,'{}'::jsonb),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('settled_at',now(),'settlement_ref',v_ref,'settlement_action',v_action,'settlement_note',p_note,'wallet_tx_id',v_wallet->>'tx_id'),updated_at=now() where id=v_req.id; return jsonb_build_object('ok',true,'idempotent',coalesce((v_wallet->>'idempotent')::boolean,false),'status',v_final_status,'external_id',coalesce(v_req.external_id,v_req.id::text),'wallet',v_wallet); end; $$;
